// Complete identifiers generated by the backend and seed scripts. Shorter
// fragments remain substring searches; IDs are stored in uppercase.
export function exactEntityId(text: string, kind: 'course' | 'user'): string | null {
  const id = text.trim().toUpperCase()
  const prefix = kind === 'course' ? 'CRS' : 'USR'
  const standard = new RegExp('^' + prefix + '-[A-Z0-9]+-(?:[0-9]{5}|[A-F0-9]{8})$')
  if (standard.test(id)) return id
  if (kind === 'user' && /^USR-ADMIN-TENANT_[A-Z0-9]+$/.test(id)) return id
  return null
}
